import{_ as s,o as a,c as t,a2 as n}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"Sovereign Desktop","description":"","frontmatter":{"sourceUrl":"https://github.com/sovereignfs/sovereign-desktop/blob/main/README.md"},"headers":[],"relativePath":"apps/desktop/index.md","filePath":"apps/desktop/index.md"}'),i={name:"apps/desktop/index.md"};function o(r,e,l,p,d,h){return a(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="sovereign-desktop" tabindex="-1">Sovereign Desktop <a class="header-anchor" href="#sovereign-desktop" aria-label="Permalink to &quot;Sovereign Desktop&quot;">​</a></h1><p>A minimal desktop shell for <a href="https://github.com/sovereignfs/sovereign" target="_blank" rel="noreferrer">Sovereign</a> — the modular, self-hostable workspace runtime. On first launch you enter your self-hosted instance URL; the app loads it in the system WebView and remembers it. All functionality is served by your own instance — this app is only the native wrapper. Multiple instances are supported.</p><p>Built with <a href="https://v2.tauri.app" target="_blank" rel="noreferrer">Tauri 2</a> (system WebView, ~5 MB binary): WKWebView on macOS, WebView2 on Windows, WebKitGTK on Linux. macOS ships first; Windows and Linux builds are produced from the same codebase.</p><p>Same model as the Nextcloud, Bitwarden, and Element desktop clients.</p><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><p>Download the installer for your platform from <a href="https://github.com/sovereignfs/sovereign-desktop/releases" target="_blank" rel="noreferrer">GitHub Releases</a>: <code>.dmg</code> (macOS 13+), <code>.msi</code>/<code>.exe</code> (Windows), <code>.AppImage</code>/<code>.deb</code> (Linux).</p><p>On launch, enter your instance URL (e.g. <code>my.sovereign.example</code>). The app checks it is a reachable Sovereign instance, then loads it. Use <strong>Instances → Switch Instance…</strong> (⌘⇧I) to add, switch, or remove instances.</p><p>Links to your own instance stay inside the app. A link to anywhere else — a third-party site, an OAuth provider, external docs — opens in your system&#39;s default browser instead of taking over the app&#39;s window.</p><p>Sovereign runs from a tray/menu-bar icon: closing the window hides it rather than quitting the app, so it stays reachable for notifications. Use the tray icon&#39;s <strong>Open</strong> to bring the window back, or <strong>Quit</strong> to fully exit.</p><p>Sovereign also registers the <code>sovereign://</code> URL scheme. A link like <code>sovereign://my.instance.example/plugins/console</code> opens the app and navigates straight to <code>/plugins/console</code> on that instance; if it isn&#39;t one of your stored instances yet, the app prompts you to add it first. On Windows/Linux, clicking a <code>sovereign://</code> link while the app is already running currently opens a second instance of the app rather than routing to the existing window — a known limitation of not yet bundling the single-instance plugin.</p><p>The app checks for updates once per launch. If a newer signed release is available, a native dialog offers <strong>Update Now</strong> (downloads, installs, and restarts the app) or <strong>Later</strong> (dismisses until the next launch). Nothing happens if you&#39;re already up to date.</p><h2 id="detecting-the-desktop-shell" tabindex="-1">Detecting the desktop shell <a class="header-anchor" href="#detecting-the-desktop-shell" aria-label="Permalink to &quot;Detecting the desktop shell&quot;">​</a></h2><p>The shell injects a frozen marker into every page it loads — including your instance — before the page&#39;s own scripts run. Web apps and plugins can read it to enable desktop-specific behaviour:</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (window.__SOVEREIGN_DESKTOP__) {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // { shell: &#39;desktop&#39;, os: &#39;macos&#39; | &#39;windows&#39; | &#39;linux&#39;, version: &#39;0.1.0&#39; }</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  const</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">os</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> window.__SOVEREIGN_DESKTOP__;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The marker is a plain, read-only data object — <strong>not</strong> a bridge to native APIs (remote instance content never gets Tauri IPC access). It is the substrate the SDK&#39;s <code>sdk.device.*</code> environment detection consumes to report the <code>&quot;desktop&quot;</code> environment (Sovereign monorepo epic task 17.7). Plugins should prefer <code>sdk.device.*</code> over reading the global directly once that lands.</p><h2 id="development" tabindex="-1">Development <a class="header-anchor" href="#development" aria-label="Permalink to &quot;Development&quot;">​</a></h2><p>Prerequisites: <a href="https://nodejs.org" target="_blank" rel="noreferrer">Node.js</a> ≥ 20, <a href="https://pnpm.io" target="_blank" rel="noreferrer">pnpm</a> 11, <a href="https://rustup.rs" target="_blank" rel="noreferrer">Rust</a> (stable). On macOS you also need Xcode command-line tools.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # tauri dev — opens the app with hot reload</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # tauri build — produces .app + .dmg (unsigned locally)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # unit tests (vitest)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> typecheck</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # tsc --noEmit</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # eslint</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> format:check</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # prettier</span></span></code></pre></div><p>To test against a local Sovereign instance, run the platform dev server (<code>pnpm dev</code> in the <code>sovereign</code> repo, port 3000) and add <code>http://localhost:3000</code> as an instance.</p><h2 id="releases" tabindex="-1">Releases <a class="header-anchor" href="#releases" aria-label="Permalink to &quot;Releases&quot;">​</a></h2><p>Pushing a <code>v*</code> tag triggers <code>.github/workflows/release.yml</code>, which builds all platform installers and attaches them to a draft GitHub Release. The macOS build is signed and notarized when these repository secrets are configured: <code>APPLE_CERTIFICATE</code>, <code>APPLE_CERTIFICATE_PASSWORD</code>, <code>APPLE_SIGNING_IDENTITY</code>, <code>APPLE_ID</code>, <code>APPLE_PASSWORD</code>, <code>APPLE_TEAM_ID</code>. Without them the <code>.dmg</code> is unsigned (Gatekeeper will warn on macOS 10.15+).</p><p>The app icons in <code>src-tauri/icons/</code> are generated from the Sovereign brand mark. To regenerate them from an updated source, run <code>pnpm tauri icon &lt;source.png&gt;</code> (1024×1024 PNG with transparency).</p><h3 id="enabling-auto-updates" tabindex="-1">Enabling auto-updates <a class="header-anchor" href="#enabling-auto-updates" aria-label="Permalink to &quot;Enabling auto-updates&quot;">​</a></h3><p>The in-app update check (epic task 17.5) ships disabled-but-wired: it&#39;s safe to build and run today, but won&#39;t find or install anything until you complete this one-time setup. <strong>Do these in order</strong> — <code>bundle.createUpdaterArtifacts</code> requires the signing key to already exist, and enabling it before the key is configured breaks every build, <code>pnpm build</code> included, not just releases:</p><ol><li>Generate a signing keypair: <code>pnpm tauri signer generate -w ~/.tauri/sovereign-desktop.key</code> (set a password when prompted — recommended, not required).</li><li>Add two repository secrets (Settings → Secrets and variables → Actions): <code>TAURI_SIGNING_PRIVATE_KEY</code> (the private key file&#39;s contents) and <code>TAURI_SIGNING_PRIVATE_KEY_PASSWORD</code> (blank if you skipped the password). <code>release.yml</code> already forwards both to the build — nothing to edit there.</li><li>Put the <strong>public</strong> key (the <code>.pub</code> file&#39;s contents, not secret) into <code>src-tauri/tauri.conf.json</code>&#39;s <code>plugins.updater.pubkey</code>, replacing the <code>REPLACE_WITH_YOUR_GENERATED_PUBLIC_KEY</code> placeholder.</li><li>Set <code>src-tauri/tauri.conf.json</code>&#39;s <code>bundle.createUpdaterArtifacts</code> to <code>true</code>.</li></ol><p>From the next tagged release onward, <code>release.yml</code> produces a signed <code>latest.json</code> update manifest alongside the installers, and the app&#39;s update check (pointed at <code>.../releases/latest/download/latest.json</code> by default) starts finding real releases.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="a-full-page-404-appears-when-opening-an-app-account-console-often-right-after-launch" tabindex="-1">A full-page 404 appears when opening an app (Account/Console), often right after launch <a class="header-anchor" href="#a-full-page-404-appears-when-opening-an-app-account-console-often-right-after-launch" aria-label="Permalink to &quot;A full-page 404 appears when opening an app (Account/Console), often right after launch&quot;">​</a></h3><p>This is served by your <strong>instance</strong>, not the shell — the desktop app is a thin WebView that renders whatever the instance returns. It is a known Next.js overlay cold-start / transient-fetch issue on the platform side; reloading the page loads the full view and clears it. See the platform troubleshooting guide for the cause and current protection: <code>docs/troubleshooting.md</code> in the <a href="https://github.com/sovereignfs/sovereign" target="_blank" rel="noreferrer">sovereign</a> repo (&quot;Full-page 404 opening an overlay route&quot;). If it persists, confirm your instance is on a build dated 2026-06-28 or later.</p><blockquote><p>Note: the shell does not yet wire a reload shortcut, so the &quot;just reload&quot; workaround isn&#39;t available in-app. A reload menu item is planned.</p></blockquote><h2 id="license" tabindex="-1">License <a class="header-anchor" href="#license" aria-label="Permalink to &quot;License&quot;">​</a></h2><p><a href="./LICENSE.html">AGPL-3.0-or-later</a></p>`,32)])])}const g=s(i,[["render",o]]);export{u as __pageData,g as default};
